jQuery(document).ready(function($) {

    const isProActive = window._gslogo_admin_data.is_pro_active == 1;
    const isLogoEditScreen = (typeof pagenow !== 'undefined' && pagenow == 'gs-logo-slider');


    // ------------------------------------------------------------------
    // Flatpickr datepickers (Logo Expire At + Client Since) - Pro only
    // ------------------------------------------------------------------
    if (isProActive && isLogoEditScreen && typeof $.fn.flatpickr === 'function') {

        $("#gs_logo_expire_at").flatpickr({
            enableTime: true,
            allowInput: true,
            dateFormat: "Y-m-d H:i:S",
            altInput: true,
            altFormat: "Y-m-d H:i:S",
            altInputClass: "gs-flatpickr-alt form-control input",
            disable: [
                function(date) {
                    const today = new Date();
                    today.setHours(0, 0, 0, 0);
                    return date < today;
                }
            ],
            onReady: function(selectedDates, dateStr, instance) {
                instance.altInput.id = "gs_logo_expire_at_field";
            }
        });

        $("#gs_logo_client_since").flatpickr({
            allowInput: true,
            dateFormat: "Y-m-d",
            altInput: true,
            altFormat: "Y-m-d",
            altInputClass: "gs-flatpickr-alt form-control input",
            maxDate: "today",
            onReady: function(selectedDates, dateStr, instance) {
                instance.altInput.id = "gs_logo_client_since_field";
            }
        });
    }


    // ------------------------------------------------------------------
    // Pitch Deck PDF uploader - Pro only (uses WP media library)
    // ------------------------------------------------------------------
    if (isProActive && isLogoEditScreen) {

        const $pdfBox       = $('#gs_logo_pitch_deck_upload');
        const $pdfIdInput   = $('#gs_logo_pitch_deck_id');
        const $pdfPreview   = $pdfBox.find('.gs-logo-pdf-preview');
        const $pdfName      = $pdfBox.find('.gs-logo-pdf-name');
        const $pdfUploadBtn = $pdfBox.find('.gs-logo-pdf-upload');
        const $pdfRemoveBtn = $pdfBox.find('.gs-logo-pdf-remove');
        let pdfFrame;

        $pdfUploadBtn.on('click', function (e) {
            e.preventDefault();

            if (pdfFrame) {
                pdfFrame.open();
                return;
            }

            pdfFrame = wp.media({
                title: $(this).data('uploader_title'),
                button: { text: $(this).data('uploader_button_text') },
                library: { type: 'application/pdf' },
                multiple: false
            });

            pdfFrame.on('select', function () {
                const attachment = pdfFrame.state().get('selection').first().toJSON();

                $pdfIdInput.val(attachment.id);
                $pdfName.attr('href', attachment.url).text(attachment.title || attachment.filename);
                $pdfPreview.show();
                $pdfUploadBtn.find('.gs-logo-metabox-action__label').text($pdfUploadBtn.data('replace-label') || 'Replace PDF');
                $pdfRemoveBtn.removeClass('gs-logo-metabox-action--hidden');
            });

            pdfFrame.on('open', function () {
                const selection = pdfFrame.state().get('selection');
                const currentId = parseInt($pdfIdInput.val(), 10);

                if (currentId > 0) {
                    const attachment = wp.media.attachment(currentId);
                    attachment.fetch();
                    selection.add(attachment ? [attachment] : []);
                }
            });

            pdfFrame.open();
        });

        $pdfRemoveBtn.on('click', function (e) {
            e.preventDefault();
            $pdfIdInput.val('');
            $pdfPreview.hide();
            $pdfName.attr('href', '').text('');
            $pdfUploadBtn.find('.gs-logo-metabox-action__label').text('Upload PDF');
            $pdfRemoveBtn.addClass('gs-logo-metabox-action--hidden');
        });
    }


    // ------------------------------------------------------------------
    // Social Links repeater - Pro only
    // Uses SortableJS for drag & drop reordering.
    // ------------------------------------------------------------------
    if (isProActive && isLogoEditScreen) {

        const $list = $('#gs_logo_social_list');

        if ($list.length) {

            let iconsMap = {};
            try {
                iconsMap = JSON.parse($list.attr('data-icons') || '{}');
            } catch (e) {
                iconsMap = {};
            }

            // Counter used to generate fresh unique indices for new rows.
            let socialRowCounter = $list.find('.gs-social-row').length;


            const buildIconOptions = function (selectedKey) {
                let html = '<option value="">— Platform —</option>';
                $.each(iconsMap, function (key, data) {
                    const isSelected = (key === selectedKey) ? ' selected' : '';
                    html += '<option value="' + key + '" data-icon="' + data.icon + '"' + isSelected + '>' + data.label + '</option>';
                });
                return html;
            };

            const getIconClass = function ($select) {
                const platformKey = $select.val();
                const $option = $select.find('option:selected');
                let iconCls = $option.attr('data-icon');

                if (!iconCls && platformKey && iconsMap[platformKey]) {
                    iconCls = iconsMap[platformKey].icon;
                }

                return iconCls || 'zmdi-link';
            };

            const getPlatformLabel = function ($select) {
                const label = ($select.find('option:selected').text() || '').trim();
                return (label && label !== '— Platform —') ? label : '';
            };

            const updateSocialRowIcon = function ($select) {
                const iconCls = getIconClass($select);
                $select.closest('.gs-social-row').find('.gs-social-icon-preview i').attr('class', 'zmdi ' + iconCls);
            };

            const updateSocialRowFromSelect = function ($select) {
                const $row = $select.closest('.gs-social-row');
                const platformLabel = getPlatformLabel($select);

                updateSocialRowIcon($select);

                if (platformLabel) {
                    $row.find('.gs-social-name').val(platformLabel);
                }

                toggleSocialUrlRequired($row);
            };

            const isSocialRowActive = function ($row) {
                const hasIcon = !!$row.find('.gs-social-icon').val();
                const hasName = !!$row.find('.gs-social-name').val().trim();
                return hasIcon || hasName;
            };

            const toggleSocialUrlRequired = function ($row) {
                const isRequired = isSocialRowActive($row);
                $row.find('.gs-social-url')
                    .prop('required', isRequired)
                    .attr('aria-required', isRequired ? 'true' : 'false');
            };

            const buildRow = function (index) {
                const namePrefix = 'gs_logo_social_links[' + index + ']';

                return '' +
                    '<div class="gs-social-row" data-index="' + index + '">' +
                        '<span class="gs-social-handle" title="Drag to reorder"><span class="dashicons dashicons-menu"></span></span>' +
                        '<span class="gs-social-icon-preview"><i class="zmdi zmdi-link"></i></span>' +
                        '<select class="gs-social-icon form-control" name="' + namePrefix + '[icon]">' +
                            buildIconOptions('') +
                        '</select>' +
                        '<input type="text" class="gs-social-name form-control" name="' + namePrefix + '[name]" value="" placeholder="Display name (optional)" />' +
                        '<input type="url" class="gs-social-url form-control" name="' + namePrefix + '[url]" value="" placeholder="https://..." />' +
                        '<button type="button" class="gs-social-remove" title="Remove"><span class="dashicons dashicons-trash"></span></button>' +
                    '</div>';
            };


            // Init SortableJS if available.
            if (typeof Sortable === 'function') {
                Sortable.create($list[0], {
                    handle: '.gs-social-handle',
                    animation: 150,
                    ghostClass: 'gs-social-row--ghost',
                    chosenClass: 'gs-social-row--chosen'
                });
            }


            // Add new row
            $('#gs_logo_social_add').on('click', function (e) {
                e.preventDefault();
                const $row = $(buildRow(socialRowCounter));
                $list.append($row);
                updateSocialRowIcon($row.find('.gs-social-icon'));
                socialRowCounter++;
            });


            // Remove row (keep at least one empty row visible).
            $list.on('click', '.gs-social-remove', function () {
                const $row = $(this).closest('.gs-social-row');

                if ($list.find('.gs-social-row').length > 1) {
                    $row.remove();
                } else {
                    $row.find('input').val('');
                    $row.find('select').val('');
                    updateSocialRowIcon($row.find('.gs-social-icon'));
                    toggleSocialUrlRequired($row);
                }
            });


            // Update icon preview + display name when platform changes.
            $list.on('change', '.gs-social-icon', function () {
                updateSocialRowFromSelect($(this));
            });

            $list.on('input', '.gs-social-name', function () {
                toggleSocialUrlRequired($(this).closest('.gs-social-row'));
            });

            // Sync icon preview for rows rendered on page load (keep saved names).
            $list.find('.gs-social-row').each(function () {
                const $row = $(this);
                updateSocialRowIcon($row.find('.gs-social-icon'));
                toggleSocialUrlRequired($row);
            });
        }
    }


    // ------------------------------------------------------------------
    // Life in Company image gallery - Pro only
    // ------------------------------------------------------------------
    if (isProActive && isLogoEditScreen) {

        const $galleryList       = $('#gs_logo_gallery_list');
        const $galleryInput      = $('#gs_logo_life_gallery_ids');
        const $galleryRemoveAll  = $('#gs_logo_gallery_remove_all');

        if ($galleryList.length && $galleryInput.length) {

            let galleryFrame;

            const toggleGalleryRemoveAll = function () {
                if ($galleryRemoveAll.length) {
                    $galleryRemoveAll.toggleClass('gs-logo-metabox-action--hidden', !$galleryList.find('.gs-logo-gallery-item').length);
                }
            };

            const syncGalleryInput = function () {
                const ids = [];
                $galleryList.find('.gs-logo-gallery-item').each(function () {
                    ids.push($(this).data('id'));
                });
                $galleryInput.val(ids.join(','));
                toggleGalleryRemoveAll();
            };

            const buildGalleryItem = function (attachment) {
                const thumbUrl = (attachment.sizes && attachment.sizes.thumbnail)
                    ? attachment.sizes.thumbnail.url
                    : attachment.url;

                return '' +
                    '<li class="gs-logo-gallery-item" data-id="' + attachment.id + '">' +
                        '<span class="gs-gallery-handle" title="Drag to reorder"><span class="dashicons dashicons-menu"></span></span>' +
                        '<div class="gs-logo-gallery-thumb"><img src="' + thumbUrl + '" alt="" /></div>' +
                        '<button type="button" class="gs-logo-gallery-remove" title="Remove"><span class="dashicons dashicons-no-alt"></span></button>' +
                    '</li>';
            };

            $('#gs_logo_gallery_add').on('click', function (e) {
                e.preventDefault();

                if (galleryFrame) {
                    galleryFrame.open();
                    return;
                }

                galleryFrame = wp.media({
                    title: $(this).data('uploader_title'),
                    button: { text: $(this).data('uploader_button_text') },
                    library: { type: 'image' },
                    multiple: 'add'
                });

                galleryFrame.on('select', function () {
                    const selection = galleryFrame.state().get('selection');

                    selection.each(function (attachment) {
                        const data = attachment.toJSON();

                        if (!$galleryList.find('[data-id="' + data.id + '"]').length) {
                            $galleryList.append(buildGalleryItem(data));
                        }
                    });

                    syncGalleryInput();
                });

                galleryFrame.on('open', function () {
                    const selection = galleryFrame.state().get('selection');

                    $galleryList.find('.gs-logo-gallery-item').each(function () {
                        const id = $(this).data('id');
                        const att = wp.media.attachment(id);
                        att.fetch();
                        selection.add(att ? [att] : []);
                    });
                });

                galleryFrame.open();
            });

            $galleryList.on('click', '.gs-logo-gallery-remove', function (e) {
                e.preventDefault();
                $(this).closest('.gs-logo-gallery-item').remove();
                syncGalleryInput();
            });

            $galleryRemoveAll.on('click', function (e) {
                e.preventDefault();
                $galleryList.empty();
                syncGalleryInput();
            });

            if (typeof Sortable === 'function') {
                Sortable.create($galleryList[0], {
                    handle: '.gs-gallery-handle',
                    animation: 150,
                    ghostClass: 'gs-logo-gallery-item--ghost',
                    onEnd: syncGalleryInput
                });
            }
        }
    }


    // ------------------------------------------------------------------
    // Title & logo image validation - required before publish/update.
    // ------------------------------------------------------------------
    if (isLogoEditScreen) {
        const titleInput = $('#title');
        const publishBtn = $('#publish');
        const thumbBox = $('#postimagediv');
        const pageHeading = $('.wp-heading-inline');
        let $validationNotice = null;

        const getThumbnailId = function () {
            const inputVal = String($('#_thumbnail_id').val() || '').trim();

            if (inputVal !== '' && inputVal !== '-1') {
                return inputVal;
            }

            if (window.wp && wp.media && wp.media.featuredImage && typeof wp.media.featuredImage.get === 'function') {
                const mediaId = wp.media.featuredImage.get();

                if (mediaId && String(mediaId) !== '' && String(mediaId) !== '-1') {
                    return String(mediaId);
                }
            }

            return '';
        };

        const hasFeaturedImage = function () {
            if (getThumbnailId() !== '') {
                return true;
            }

            return thumbBox.find('.inside img').length > 0;
        };

        const clearValidationStyles = function () {
            titleInput.css({ 'border-color': '', 'box-shadow': '' });
            thumbBox.css({ 'border': '', 'box-shadow': '' });
        };

        const hideValidationNotice = function () {
            if ($validationNotice) {
                $validationNotice.removeClass('is-visible');
            }
        };

        const showValidationNotice = function (missing) {
            const message = 'Please add ' + missing.join(' and ') + ' before publishing or updating.';

            if (!$validationNotice) {
                $validationNotice = $(
                    '<div class="gs-logo-validation-notice" role="alert" aria-live="polite">' +
                        '<span class="gs-logo-validation-notice__icon dashicons dashicons-warning" aria-hidden="true"></span>' +
                        '<div class="gs-logo-validation-notice__content">' +
                            '<strong class="gs-logo-validation-notice__title">Cannot publish yet</strong>' +
                            '<p class="gs-logo-validation-notice__message"></p>' +
                        '</div>' +
                        '<button type="button" class="gs-logo-validation-notice__dismiss" aria-label="Dismiss notice">' +
                            '<span class="dashicons dashicons-no-alt" aria-hidden="true"></span>' +
                        '</button>' +
                    '</div>'
                );

                if (pageHeading.length) {
                    pageHeading.after($validationNotice);
                } else {
                    $('.wrap').first().prepend($validationNotice);
                }

                $validationNotice.on('click', '.gs-logo-validation-notice__dismiss', function () {
                    hideValidationNotice();
                    clearValidationStyles();
                });
            }

            $validationNotice.find('.gs-logo-validation-notice__message').text(message);
            $validationNotice.addClass('is-visible');

            $('html, body').animate({ scrollTop: $validationNotice.offset().top - 32 }, 300);
        };

        const onThumbnailChange = function () {
            if (hasFeaturedImage()) {
                thumbBox.css({ 'border': '', 'box-shadow': '' });
            }

            if (titleInput.val().trim() !== '' && hasFeaturedImage()) {
                hideValidationNotice();
            }
        };

        titleInput.on('input', function () {
            if ($(this).val().trim() !== '') {
                titleInput.css({ 'border-color': '', 'box-shadow': '' });
            }

            if ($(this).val().trim() !== '' && hasFeaturedImage()) {
                hideValidationNotice();
            }
        });

        if (thumbBox.length) {
            thumbBox.on('click', '#remove-post-thumbnail', onThumbnailChange);

            const thumbInside = thumbBox.find('.inside')[0];

            if (thumbInside && window.MutationObserver) {
                new MutationObserver(onThumbnailChange).observe(thumbInside, {
                    childList: true,
                    subtree: true,
                    attributes: true,
                    attributeFilter: ['value']
                });
            }
        }

        publishBtn.on('click', function (e) {
            const titleVal = titleInput.val().trim();
            const missing = [];

            clearValidationStyles();
            hideValidationNotice();

            if (titleVal === '') {
                missing.push('a title');
            }

            if (!hasFeaturedImage()) {
                missing.push('a logo image');
            }

            if (!missing.length) {
                return;
            }

            e.preventDefault();

            showValidationNotice(missing);

            if (titleVal === '') {
                titleInput.css({ 'border-color': 'red', 'box-shadow': '0 0 0 1px red' }).focus();
            }

            if (!hasFeaturedImage()) {
                thumbBox.css({ 'border': '1px solid red', 'box-shadow': '0 0 0 1px red' });
            }
        });
    }

});
